import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as r}from"./app-BDkXanxw.js";var i=JSON.parse(`{"path":"/%E8%BF%90%E7%BB%B4%E4%B8%8E%E9%83%A8%E7%BD%B2/Linux%E5%9F%BA%E7%A1%80/01.%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%E4%B8%8E%E7%9B%AE%E5%BD%95%E7%BB%93%E6%9E%84.html","title":"文件系统与目录结构","lang":"zh-CN","frontmatter":{"title":"文件系统与目录结构","date":"2025-04-14T00:00:00.000Z","category":["Linux基础"],"tag":["Linux","文件系统","目录结构","运维"],"order":1},"git":{"createdTime":1776135420000,"updatedTime":1776135420000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":8.14,"words":2442},"filePathRelative":"运维与部署/Linux基础/01.文件系统与目录结构.md"}`),a={name:`01.文件系统与目录结构.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="文件系统与目录结构" tabindex="-1"><a class="header-anchor" href="#文件系统与目录结构"><span>文件系统与目录结构</span></a></h1><p>拿到一台新服务器，第一件事不是装软件，是搞清楚东西放在哪。</p><p>Linux 不像 Windows 有 C盘 D盘，整个系统就是一棵目录树，根节点是 <code>/</code>。</p><hr><h2 id="目录树全景" tabindex="-1"><a class="header-anchor" href="#目录树全景"><span>目录树全景</span></a></h2><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>/</span></span>
<span class="line"><span>├── bin/        → 基础命令（ls, cp, cat, grep...）</span></span>
<span class="line"><span>├── sbin/       → 系统管理命令（systemctl, fdisk, iptables...）</span></span>
<span class="line"><span>├── etc/        → 配置文件（nginx.conf, sshd_config, hosts...）</span></span>
<span class="line"><span>├── home/       → 普通用户的家目录（/home/deploy, /home/zhangsan）</span></span>
<span class="line"><span>├── root/       → root 用户的家目录</span></span>
<span class="line"><span>├── var/        → 可变数据</span></span>
<span class="line"><span>│   ├── log/    → 系统日志（messages, secure, dmesg）</span></span>
<span class="line"><span>│   ├── lib/    → 程序运行数据（mysql, docker）</span></span>
<span class="line"><span>│   └── run/    → 运行时文件（pid文件）</span></span>
<span class="line"><span>├── tmp/        → 临时文件（重启会清空）</span></span>
<span class="line"><span>├── usr/        → 用户程序（类似 Windows 的 Program Files）</span></span>
<span class="line"><span>│   ├── bin/    → 用户命令</span></span>
<span class="line"><span>│   ├── lib/    → 库文件</span></span>
<span class="line"><span>│   ├── local/  → 手动安装的软件（/usr/local/nginx）</span></span>
<span class="line"><span>│   └── share/  → 共享资源（文档、字体）</span></span>
<span class="line"><span>├── opt/        → 第三方大型软件（/opt/dotnet, /opt/gitlab）</span></span>
<span class="line"><span>├── proc/       → 虚拟文件系统，映射内核信息（/proc/cpuinfo）</span></span>
<span class="line"><span>├── sys/        → 虚拟文件系统，映射硬件信息</span></span>
<span class="line"><span>├── dev/        → 设备文件（/dev/sda = 第一块硬盘）</span></span>
<span class="line"><span>├── mnt/        → 临时挂载点</span></span>
<span class="line"><span>├── media/      → 可移动设备挂载点（U盘、光驱）</span></span>
<span class="line"><span>├── boot/       → 内核和启动文件</span></span>
<span class="line"><span>└── lib/        → 系统库文件（.so 动态链接库）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>太多了记不住没关系，日常只需要盯住这几个：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>/etc/        → 改配置来这里</span></span>
<span class="line"><span>/var/log/    → 查日志来这里</span></span>
<span class="line"><span>/opt/ 或 /usr/local/  → 装软件来这里</span></span>
<span class="line"><span>/home/deploy → 放应用来这里</span></span>
<span class="line"><span>/tmp/        → 临时扔东西来这里</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="做-net-部署你会碰到的目录" tabindex="-1"><a class="header-anchor" href="#做-net-部署你会碰到的目录"><span>做 .NET 部署你会碰到的目录</span></a></h2><h3 id="你的应用放哪" tabindex="-1"><a class="header-anchor" href="#你的应用放哪"><span>你的应用放哪？</span></a></h3><p>两种常见方案：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 方案一：放 /opt 下（推荐，和 Docker/GitLab 等放一起）</span></span>
<span class="line"><span style="color:#61AFEF;">/opt/apps/</span></span>
<span class="line"><span style="color:#61AFEF;">├──</span><span style="color:#98C379;"> erp-api/</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">   ├──</span><span style="color:#98C379;"> ERP.Host.dll</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">   ├──</span><span style="color:#98C379;"> appsettings.json</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">   ├──</span><span style="color:#98C379;"> appsettings.Production.json</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">   └──</span><span style="color:#98C379;"> logs/</span></span>
<span class="line"><span style="color:#61AFEF;">├──</span><span style="color:#98C379;"> sso-server/</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">   ├──</span><span style="color:#98C379;"> SSO.Host.dll</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">   └──</span><span style="color:#98C379;"> ...</span></span>
<span class="line"><span style="color:#61AFEF;">└──</span><span style="color:#98C379;"> auth-center/</span></span>
<span class="line"><span style="color:#61AFEF;">    └──</span><span style="color:#98C379;"> ...</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 方案二：放用户家目录下</span></span>
<span class="line"><span style="color:#61AFEF;">/home/deploy/apps/</span></span>
<span class="line"><span style="color:#61AFEF;">├──</span><span style="color:#98C379;"> erp-api/</span></span>
<span class="line"><span style="color:#61AFEF;">└──</span><span style="color:#98C379;"> sso-server/</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>选哪个都行，关键是<strong>统一</strong>，别这个项目放 /opt 那个放 /home，过俩月你自己都找不到。</p><h3 id="日志放哪" tabindex="-1"><a class="header-anchor" href="#日志放哪"><span>日志放哪？</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 方案一：应用目录下的 logs 子目录</span></span>
<span class="line"><span style="color:#61AFEF;">/opt/apps/erp-api/logs/</span></span>
<span class="line"><span style="color:#61AFEF;">├──</span><span style="color:#98C379;"> 2024-04-14.log</span></span>
<span class="line"><span style="color:#61AFEF;">└──</span><span style="color:#98C379;"> 2024-04-13.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 方案二：集中到 /var/log 下（方便统一收集）</span></span>
<span class="line"><span style="color:#61AFEF;">/var/log/apps/</span></span>
<span class="line"><span style="color:#61AFEF;">├──</span><span style="color:#98C379;"> erp-api/</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">   └──</span><span style="color:#98C379;"> app.log</span></span>
<span class="line"><span style="color:#61AFEF;">└──</span><span style="color:#98C379;"> sso-server/</span></span>
<span class="line"><span style="color:#61AFEF;">    └──</span><span style="color:#98C379;"> app.log</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用 Serilog 的话，在 <code>appsettings.Production.json</code> 里配路径就行：</p><div class="language-json line-numbers-mode" data-highlighter="shiki" data-ext="json" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-json"><span class="line"><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;Serilog&quot;</span><span style="color:#ABB2BF;">: {</span></span>
<span class="line"><span style="color:#E06C75;">    &quot;WriteTo&quot;</span><span style="color:#ABB2BF;">: [</span></span>
<span class="line"><span style="color:#ABB2BF;">      {</span></span>
<span class="line"><span style="color:#E06C75;">        &quot;Name&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;File&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">        &quot;Args&quot;</span><span style="color:#ABB2BF;">: {</span></span>
<span class="line"><span style="color:#E06C75;">          &quot;path&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;/opt/apps/erp-api/logs/app-.log&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">          &quot;rollingInterval&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;Day&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">          &quot;retainedFileCountLimit&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">30</span></span>
<span class="line"><span style="color:#ABB2BF;">        }</span></span>
<span class="line"><span style="color:#ABB2BF;">      }</span></span>
<span class="line"><span style="color:#ABB2BF;">    ]</span></span>
<span class="line"><span style="color:#ABB2BF;">  }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="docker-相关目录" tabindex="-1"><a class="header-anchor" href="#docker-相关目录"><span>Docker 相关目录</span></a></h3><p>装了 Docker 之后，这几个目录会出现：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">/var/lib/docker/</span><span style="color:#98C379;">        →</span><span style="color:#98C379;"> Docker</span><span style="color:#98C379;"> 的数据目录（镜像、容器、卷）</span></span>
<span class="line"><span style="color:#61AFEF;">  ├──</span><span style="color:#98C379;"> image/</span><span style="color:#98C379;">            →</span><span style="color:#98C379;"> 镜像存储</span></span>
<span class="line"><span style="color:#61AFEF;">  ├──</span><span style="color:#98C379;"> containers/</span><span style="color:#98C379;">       →</span><span style="color:#98C379;"> 容器数据</span></span>
<span class="line"><span style="color:#61AFEF;">  ├──</span><span style="color:#98C379;"> volumes/</span><span style="color:#98C379;">          →</span><span style="color:#98C379;"> 数据卷</span></span>
<span class="line"><span style="color:#61AFEF;">  └──</span><span style="color:#98C379;"> overlay2/</span><span style="color:#98C379;">         →</span><span style="color:#98C379;"> 联合文件系统层（最占空间的地方）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">/etc/docker/</span><span style="color:#98C379;">            →</span><span style="color:#98C379;"> Docker</span><span style="color:#98C379;"> 配置</span></span>
<span class="line"><span style="color:#61AFEF;">  └──</span><span style="color:#98C379;"> daemon.json</span><span style="color:#98C379;">       →</span><span style="color:#98C379;"> Docker</span><span style="color:#98C379;"> 守护进程配置</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ⚠️ /var/lib/docker 会越来越大</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 生产环境建议把它挂到大磁盘分区</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="文件操作命令速查" tabindex="-1"><a class="header-anchor" href="#文件操作命令速查"><span>文件操作命令速查</span></a></h2><h3 id="导航与查看" tabindex="-1"><a class="header-anchor" href="#导航与查看"><span>导航与查看</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 当前在哪？</span></span>
<span class="line"><span style="color:#56B6C2;">pwd</span><span style="color:#7F848E;font-style:italic;">                         # /home/deploy</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 列目录</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#7F848E;font-style:italic;">                          # 简单列出</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#7F848E;font-style:italic;">                      # 详细列出（权限、大小、时间）</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -lh</span><span style="color:#7F848E;font-style:italic;">                      # 人类可读的大小（K/M/G）</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -lt</span><span style="color:#7F848E;font-style:italic;">                      # 按修改时间排序（最新在前）</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -lS</span><span style="color:#7F848E;font-style:italic;">                      # 按文件大小排序</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 切换目录</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> /opt/apps/erp-api</span><span style="color:#7F848E;font-style:italic;">        # 绝对路径</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> ..</span><span style="color:#7F848E;font-style:italic;">                       # 上一级</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> ~</span><span style="color:#7F848E;font-style:italic;">                        # 回家目录</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> -</span><span style="color:#7F848E;font-style:italic;">                        # 回到上一次所在的目录（很好用）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 看目录树结构</span></span>
<span class="line"><span style="color:#61AFEF;">tree</span><span style="color:#98C379;"> /opt/apps</span><span style="color:#7F848E;font-style:italic;">              # 需要先装：yum install tree</span></span>
<span class="line"><span style="color:#61AFEF;">tree</span><span style="color:#D19A66;"> -L</span><span style="color:#D19A66;"> 2</span><span style="color:#98C379;"> /opt/apps</span><span style="color:#7F848E;font-style:italic;">         # 只看两层</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="文件操作" tabindex="-1"><a class="header-anchor" href="#文件操作"><span>文件操作</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 创建</span></span>
<span class="line"><span style="color:#61AFEF;">mkdir</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> /opt/apps/erp-api/logs</span><span style="color:#7F848E;font-style:italic;">    # -p 递归创建（父目录不存在也不报错）</span></span>
<span class="line"><span style="color:#61AFEF;">touch</span><span style="color:#98C379;"> app.log</span><span style="color:#7F848E;font-style:italic;">                       # 创建空文件（或更新时间戳）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 复制</span></span>
<span class="line"><span style="color:#61AFEF;">cp</span><span style="color:#98C379;"> appsettings.json</span><span style="color:#98C379;"> appsettings.json.bak</span><span style="color:#7F848E;font-style:italic;">    # 备份配置</span></span>
<span class="line"><span style="color:#61AFEF;">cp</span><span style="color:#D19A66;"> -r</span><span style="color:#98C379;"> erp-api/</span><span style="color:#98C379;"> erp-api-backup/</span><span style="color:#7F848E;font-style:italic;">              # 复制整个目录（-r 递归）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 移动/重命名</span></span>
<span class="line"><span style="color:#61AFEF;">mv</span><span style="color:#98C379;"> app.log</span><span style="color:#98C379;"> app.log.old</span><span style="color:#7F848E;font-style:italic;">                       # 重命名</span></span>
<span class="line"><span style="color:#61AFEF;">mv</span><span style="color:#98C379;"> /tmp/publish/</span><span style="color:#E5C07B;">*</span><span style="color:#98C379;"> /opt/apps/erp-api/</span><span style="color:#7F848E;font-style:italic;">         # 移动文件</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除</span></span>
<span class="line"><span style="color:#61AFEF;">rm</span><span style="color:#98C379;"> app.log</span><span style="color:#7F848E;font-style:italic;">                                   # 删文件</span></span>
<span class="line"><span style="color:#61AFEF;">rm</span><span style="color:#D19A66;"> -rf</span><span style="color:#98C379;"> /opt/apps/erp-api-old/</span><span style="color:#7F848E;font-style:italic;">               # ⚠️ 删目录（不可恢复！）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 软链接（快捷方式）</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> /opt/apps/erp-api/current</span><span style="color:#98C379;"> /opt/apps/erp-api/releases/v1.2.3</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 部署新版本时只需更新软链接指向，回滚也只是换个指向</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">关于 rm -rf</p><p><code>rm -rf /</code> 会删掉整个系统，不会有任何提示。</p><p>实际工作中的安全习惯：</p><ol><li>删除前先 <code>ls</code> 确认路径是对的</li><li>变量拼路径时加引号：<code>rm -rf &quot;\${APP_DIR}&quot;</code> 而不是 <code>rm -rf $APP_DIR</code></li><li>如果 <code>$APP_DIR</code> 为空，<code>rm -rf $APP_DIR/</code> 会变成 <code>rm -rf /</code>，引号可以防住</li></ol></div><h3 id="文件内容查看" tabindex="-1"><a class="header-anchor" href="#文件内容查看"><span>文件内容查看</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 整个文件</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> nginx.conf</span><span style="color:#7F848E;font-style:italic;">                # 小文件直接看</span></span>
<span class="line"><span style="color:#61AFEF;">less</span><span style="color:#98C379;"> nginx.conf</span><span style="color:#7F848E;font-style:italic;">               # 大文件分页看（q 退出，/关键词 搜索）</span></span>
<span class="line"><span style="color:#61AFEF;">head</span><span style="color:#D19A66;"> -20</span><span style="color:#98C379;"> app.log</span><span style="color:#7F848E;font-style:italic;">              # 看前 20 行</span></span>
<span class="line"><span style="color:#61AFEF;">tail</span><span style="color:#D19A66;"> -50</span><span style="color:#98C379;"> app.log</span><span style="color:#7F848E;font-style:italic;">              # 看最后 50 行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ⭐ 实时追踪日志（排查问题最常用）</span></span>
<span class="line"><span style="color:#61AFEF;">tail</span><span style="color:#D19A66;"> -f</span><span style="color:#98C379;"> /opt/apps/erp-api/logs/app.log</span></span>
<span class="line"><span style="color:#61AFEF;">tail</span><span style="color:#D19A66;"> -f</span><span style="color:#98C379;"> /var/log/nginx/error.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 多个日志同时追踪</span></span>
<span class="line"><span style="color:#61AFEF;">tail</span><span style="color:#D19A66;"> -f</span><span style="color:#98C379;"> /opt/apps/erp-api/logs/app.log</span><span style="color:#98C379;"> /var/log/nginx/error.log</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="搜索" tabindex="-1"><a class="header-anchor" href="#搜索"><span>搜索</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 在文件内容中搜索</span></span>
<span class="line"><span style="color:#61AFEF;">grep</span><span style="color:#98C379;"> &quot;Exception&quot;</span><span style="color:#98C379;"> app.log</span><span style="color:#7F848E;font-style:italic;">                    # 找异常</span></span>
<span class="line"><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &quot;error&quot;</span><span style="color:#98C379;"> app.log</span><span style="color:#7F848E;font-style:italic;">                     # -i 忽略大小写</span></span>
<span class="line"><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &quot;500&quot;</span><span style="color:#98C379;"> access.log</span><span style="color:#7F848E;font-style:italic;">                    # -n 显示行号</span></span>
<span class="line"><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -r</span><span style="color:#98C379;"> &quot;ConnectionString&quot;</span><span style="color:#98C379;"> /opt/apps/</span><span style="color:#7F848E;font-style:italic;">       # -r 递归搜索目录</span></span>
<span class="line"><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -c</span><span style="color:#98C379;"> &quot;404&quot;</span><span style="color:#98C379;"> access.log</span><span style="color:#7F848E;font-style:italic;">                    # -c 只统计匹配数量</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 搜索文件</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /opt/apps</span><span style="color:#D19A66;"> -name</span><span style="color:#98C379;"> &quot;appsettings*.json&quot;</span><span style="color:#7F848E;font-style:italic;">               # 按名字找</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /opt/apps</span><span style="color:#D19A66;"> -name</span><span style="color:#98C379;"> &quot;*.log&quot;</span><span style="color:#D19A66;"> -mtime</span><span style="color:#98C379;"> +30</span><span style="color:#7F848E;font-style:italic;">                # 30天前的日志</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /opt/apps</span><span style="color:#D19A66;"> -name</span><span style="color:#98C379;"> &quot;*.log&quot;</span><span style="color:#D19A66;"> -mtime</span><span style="color:#98C379;"> +30</span><span style="color:#D19A66;"> -delete</span><span style="color:#7F848E;font-style:italic;">        # 找到并删除</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /</span><span style="color:#D19A66;"> -name</span><span style="color:#98C379;"> &quot;dotnet&quot;</span><span style="color:#D19A66;"> -type</span><span style="color:#98C379;"> f</span><span style="color:#7F848E;font-style:italic;">                          # 找 dotnet 可执行文件</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /var/log</span><span style="color:#D19A66;"> -size</span><span style="color:#98C379;"> +100M</span><span style="color:#7F848E;font-style:italic;">                              # 找大于100M的文件</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># which / whereis：找命令在哪</span></span>
<span class="line"><span style="color:#56B6C2;">which</span><span style="color:#98C379;"> dotnet</span><span style="color:#7F848E;font-style:italic;">                  # /usr/bin/dotnet</span></span>
<span class="line"><span style="color:#56B6C2;">which</span><span style="color:#98C379;"> nginx</span><span style="color:#7F848E;font-style:italic;">                   # /usr/sbin/nginx</span></span>
<span class="line"><span style="color:#61AFEF;">whereis</span><span style="color:#98C379;"> docker</span><span style="color:#7F848E;font-style:italic;">                # 显示二进制、源码、手册页位置</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="磁盘空间管理" tabindex="-1"><a class="header-anchor" href="#磁盘空间管理"><span>磁盘空间管理</span></a></h2><p>服务器跑着跑着磁盘满了，这是你一定会碰到的问题。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看磁盘使用情况</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -h</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输出示例：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Filesystem      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /dev/sda1        50G   38G   12G  76% /</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /dev/sdb1       200G   89G  111G  45% /data</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看当前目录下每个子目录的大小</span></span>
<span class="line"><span style="color:#61AFEF;">du</span><span style="color:#D19A66;"> -sh</span><span style="color:#E5C07B;"> *</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输出示例：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2.3G    docker</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 150M    erp-api</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 80M     sso-server</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 找出最占空间的目录（从大到小）</span></span>
<span class="line"><span style="color:#61AFEF;">du</span><span style="color:#D19A66;"> -sh</span><span style="color:#98C379;"> /</span><span style="color:#E5C07B;">*</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sort</span><span style="color:#D19A66;"> -rh</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">head</span><span style="color:#D19A66;"> -10</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 这条命令排查磁盘满的时候特别好用</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 从根目录开始，逐层往下找，定位到具体是哪个目录在吃空间</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Docker 占空间排查</span></span>
<span class="line"><span style="color:#61AFEF;">docker</span><span style="color:#98C379;"> system</span><span style="color:#98C379;"> df</span><span style="color:#7F848E;font-style:italic;">              # 看镜像/容器/卷各占多少</span></span>
<span class="line"><span style="color:#61AFEF;">docker</span><span style="color:#98C379;"> system</span><span style="color:#98C379;"> prune</span><span style="color:#D19A66;"> -a</span><span style="color:#7F848E;font-style:italic;">        # ⚠️ 清理所有未使用的（慎用）</span></span>
<span class="line"><span style="color:#61AFEF;">docker</span><span style="color:#98C379;"> image</span><span style="color:#98C379;"> prune</span><span style="color:#7F848E;font-style:italic;">            # 只清理悬空镜像</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="磁盘满了的排查套路" tabindex="-1"><a class="header-anchor" href="#磁盘满了的排查套路"><span>磁盘满了的排查套路</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>Step 1: df -h 看哪个分区满了</span></span>
<span class="line"><span>Step 2: cd 到那个分区的挂载点</span></span>
<span class="line"><span>Step 3: du -sh * | sort -rh | head 找最大的目录</span></span>
<span class="line"><span>Step 4: cd 进去，重复 Step 3，直到定位到具体文件</span></span>
<span class="line"><span>Step 5: 确认可以删除后，rm 或 truncate</span></span>
<span class="line"><span></span></span>
<span class="line"><span>常见元凶：</span></span>
<span class="line"><span>  /var/log/       → 日志没有轮转</span></span>
<span class="line"><span>  /var/lib/docker → 废弃的镜像和容器</span></span>
<span class="line"><span>  /tmp/           → 临时文件没清理</span></span>
<span class="line"><span>  应用的 logs 目录  → 没配置日志保留策略</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="日志轮转配置" tabindex="-1"><a class="header-anchor" href="#日志轮转配置"><span>日志轮转配置</span></a></h3><p>别等磁盘满了才想起来。装完应用就把日志轮转配上：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># /etc/logrotate.d/erp-api</span></span>
<span class="line"><span style="color:#61AFEF;">/opt/apps/erp-api/logs/*.log</span><span style="color:#98C379;"> {</span></span>
<span class="line"><span style="color:#61AFEF;">    daily</span><span style="color:#7F848E;font-style:italic;">               # 每天轮转</span></span>
<span class="line"><span style="color:#61AFEF;">    rotate</span><span style="color:#D19A66;"> 30</span><span style="color:#7F848E;font-style:italic;">           # 保留 30 天</span></span>
<span class="line"><span style="color:#61AFEF;">    compress</span><span style="color:#7F848E;font-style:italic;">            # 压缩旧日志</span></span>
<span class="line"><span style="color:#61AFEF;">    delaycompress</span><span style="color:#7F848E;font-style:italic;">       # 延迟一天再压缩</span></span>
<span class="line"><span style="color:#61AFEF;">    missingok</span><span style="color:#7F848E;font-style:italic;">           # 日志文件不存在不报错</span></span>
<span class="line"><span style="color:#61AFEF;">    notifempty</span><span style="color:#7F848E;font-style:italic;">          # 空文件不轮转</span></span>
<span class="line"><span style="color:#61AFEF;">    copytruncate</span><span style="color:#7F848E;font-style:italic;">        # 复制后清空（不影响正在写入的进程）</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 测试轮转配置是否正确</span></span>
<span class="line"><span style="color:#61AFEF;">logrotate</span><span style="color:#D19A66;"> -d</span><span style="color:#98C379;"> /etc/logrotate.d/erp-api</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 手动执行一次轮转</span></span>
<span class="line"><span style="color:#61AFEF;">logrotate</span><span style="color:#D19A66;"> -f</span><span style="color:#98C379;"> /etc/logrotate.d/erp-api</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="文件压缩与传输" tabindex="-1"><a class="header-anchor" href="#文件压缩与传输"><span>文件压缩与传输</span></a></h2><h3 id="压缩-解压" tabindex="-1"><a class="header-anchor" href="#压缩-解压"><span>压缩/解压</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># tar.gz（最常见）</span></span>
<span class="line"><span style="color:#61AFEF;">tar</span><span style="color:#D19A66;"> -czf</span><span style="color:#98C379;"> erp-api-v1.2.3.tar.gz</span><span style="color:#98C379;"> erp-api/</span><span style="color:#7F848E;font-style:italic;">     # 打包压缩</span></span>
<span class="line"><span style="color:#61AFEF;">tar</span><span style="color:#D19A66;"> -xzf</span><span style="color:#98C379;"> erp-api-v1.2.3.tar.gz</span><span style="color:#7F848E;font-style:italic;">              # 解压</span></span>
<span class="line"><span style="color:#61AFEF;">tar</span><span style="color:#D19A66;"> -xzf</span><span style="color:#98C379;"> erp-api-v1.2.3.tar.gz</span><span style="color:#D19A66;"> -C</span><span style="color:#98C379;"> /opt/apps</span><span style="color:#7F848E;font-style:italic;"> # 解压到指定目录</span></span>
<span class="line"><span style="color:#61AFEF;">tar</span><span style="color:#D19A66;"> -tzf</span><span style="color:#98C379;"> erp-api-v1.2.3.tar.gz</span><span style="color:#7F848E;font-style:italic;">              # 只看内容，不解压</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># zip（和 Windows 交互时用）</span></span>
<span class="line"><span style="color:#61AFEF;">zip</span><span style="color:#D19A66;"> -r</span><span style="color:#98C379;"> erp-api.zip</span><span style="color:#98C379;"> erp-api/</span></span>
<span class="line"><span style="color:#61AFEF;">unzip</span><span style="color:#98C379;"> erp-api.zip</span><span style="color:#D19A66;"> -d</span><span style="color:#98C379;"> /opt/apps</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>参数记忆：</p><ul><li><code>-c</code> create（创建）</li><li><code>-x</code> extract（解压）</li><li><code>-z</code> gzip（压缩算法）</li><li><code>-f</code> file（指定文件名，必须放最后）</li><li><code>-v</code> verbose（显示过程）</li><li><code>-C</code> 指定解压目录</li></ul><h3 id="文件传输" tabindex="-1"><a class="header-anchor" href="#文件传输"><span>文件传输</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 从本机上传到服务器</span></span>
<span class="line"><span style="color:#61AFEF;">scp</span><span style="color:#98C379;"> publish.tar.gz</span><span style="color:#98C379;"> deploy@192.168.1.100:/opt/apps/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 从服务器下载到本机</span></span>
<span class="line"><span style="color:#61AFEF;">scp</span><span style="color:#98C379;"> deploy@192.168.1.100:/opt/apps/erp-api/logs/app.log</span><span style="color:#98C379;"> ./</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 上传整个目录</span></span>
<span class="line"><span style="color:#61AFEF;">scp</span><span style="color:#D19A66;"> -r</span><span style="color:#98C379;"> ./publish/</span><span style="color:#98C379;"> deploy@192.168.1.100:/opt/apps/erp-api/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># rsync（增量同步，比 scp 快，适合部署）</span></span>
<span class="line"><span style="color:#61AFEF;">rsync</span><span style="color:#D19A66;"> -avz</span><span style="color:#D19A66;"> --delete</span><span style="color:#98C379;"> ./publish/</span><span style="color:#98C379;"> deploy@192.168.1.100:/opt/apps/erp-api/</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># -a 归档模式（保留权限、时间戳等）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># -v 显示过程</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># -z 压缩传输</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># --delete 目标端多余的文件删掉（和源保持一致）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="环境变量" tabindex="-1"><a class="header-anchor" href="#环境变量"><span>环境变量</span></a></h2><p>.NET 应用经常通过环境变量传配置（数据库连接串、密钥等）。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看所有环境变量</span></span>
<span class="line"><span style="color:#61AFEF;">env</span></span>
<span class="line"><span style="color:#61AFEF;">printenv</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看特定变量</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#E06C75;"> $PATH</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#E06C75;"> $ASPNETCORE_ENVIRONMENT</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#E06C75;"> $DOTNET_ROOT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 临时设置（当前会话有效）</span></span>
<span class="line"><span style="color:#C678DD;">export</span><span style="color:#E06C75;"> ASPNETCORE_ENVIRONMENT</span><span style="color:#56B6C2;">=</span><span style="color:#E06C75;">Production</span></span>
<span class="line"><span style="color:#C678DD;">export</span><span style="color:#E06C75;"> ASPNETCORE_URLS</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&quot;http://0.0.0.0:5000&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 永久设置 —— 方法一：写到用户配置文件</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;export ASPNETCORE_ENVIRONMENT=Production&#39;</span><span style="color:#ABB2BF;"> &gt;&gt; </span><span style="color:#98C379;">~/.bashrc</span></span>
<span class="line"><span style="color:#56B6C2;">source</span><span style="color:#98C379;"> ~/.bashrc</span><span style="color:#7F848E;font-style:italic;">    # 使其立即生效</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 永久设置 —— 方法二：写到 /etc/profile.d/（对所有用户生效）</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#ABB2BF;"> &gt; </span><span style="color:#98C379;">/etc/profile.d/dotnet.sh</span><span style="color:#ABB2BF;"> &lt;&lt; </span><span style="color:#ABB2BF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="color:#98C379;">export DOTNET_ROOT=/opt/dotnet</span></span>
<span class="line"><span style="color:#98C379;">export PATH=$PATH:$DOTNET_ROOT</span></span>
<span class="line"><span style="color:#98C379;">export ASPNETCORE_ENVIRONMENT=Production</span></span>
<span class="line"><span style="color:#ABB2BF;">EOF</span></span>
<span class="line"><span style="color:#56B6C2;">source</span><span style="color:#98C379;"> /etc/profile.d/dotnet.sh</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在 systemd 服务中设置（推荐，只对该服务生效）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在 .service 文件的 [Service] 段加：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Environment=ASPNETCORE_ENVIRONMENT=Production</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Environment=ASPNETCORE_URLS=http://0.0.0.0:5000</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="path-变量" tabindex="-1"><a class="header-anchor" href="#path-变量"><span>PATH 变量</span></a></h3><p>PATH 决定了你在终端输入命令时，系统去哪些目录找可执行文件。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#E06C75;"> $PATH</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/root/bin</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 装了 .NET 但输入 dotnet 提示找不到？大概率是 PATH 没配</span></span>
<span class="line"><span style="color:#56B6C2;">which</span><span style="color:#98C379;"> dotnet</span><span style="color:#7F848E;font-style:italic;">    # 如果没输出，说明 PATH 里没有</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 手动找到 dotnet 在哪</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /</span><span style="color:#D19A66;"> -name</span><span style="color:#98C379;"> &quot;dotnet&quot;</span><span style="color:#D19A66;"> -type</span><span style="color:#98C379;"> f</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /opt/dotnet/dotnet</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 加到 PATH</span></span>
<span class="line"><span style="color:#C678DD;">export</span><span style="color:#E06C75;"> PATH</span><span style="color:#56B6C2;">=</span><span style="color:#E06C75;">$PATH</span><span style="color:#ABB2BF;">:/</span><span style="color:#E06C75;">opt</span><span style="color:#ABB2BF;">/</span><span style="color:#E06C75;">dotnet</span></span>
<span class="line"><span style="color:#61AFEF;">dotnet</span><span style="color:#D19A66;"> --version</span><span style="color:#7F848E;font-style:italic;">    # 现在能用了</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="速查表" tabindex="-1"><a class="header-anchor" href="#速查表"><span>速查表</span></a></h2><table><thead><tr><th>场景</th><th>命令</th></tr></thead><tbody><tr><td>我在哪</td><td><code>pwd</code></td></tr><tr><td>看目录内容</td><td><code>ls -lh</code></td></tr><tr><td>切到上次的目录</td><td><code>cd -</code></td></tr><tr><td>递归创建目录</td><td><code>mkdir -p a/b/c</code></td></tr><tr><td>实时看日志</td><td><code>tail -f app.log</code></td></tr><tr><td>搜文件内容</td><td><code>grep -rn &quot;关键词&quot; ./</code></td></tr><tr><td>找文件</td><td><code>find / -name &quot;文件名&quot;</code></td></tr><tr><td>磁盘告急</td><td><code>du -sh * | sort -rh | head</code></td></tr><tr><td>看磁盘分区</td><td><code>df -h</code></td></tr><tr><td>打包</td><td><code>tar -czf 包名.tar.gz 目录/</code></td></tr><tr><td>解包</td><td><code>tar -xzf 包名.tar.gz -C 目标目录</code></td></tr><tr><td>上传文件</td><td><code>scp 文件 user@ip:路径</code></td></tr><tr><td>增量同步</td><td><code>rsync -avz 源/ user@ip:目标/</code></td></tr><tr><td>设置环境变量</td><td><code>export KEY=VALUE</code></td></tr><tr><td>找命令位置</td><td><code>which 命令名</code></td></tr></tbody></table><hr><h2 id="动手练习" tabindex="-1"><a class="header-anchor" href="#动手练习"><span>动手练习</span></a></h2><p>拿到一台新 CentOS 服务器后，按顺序操作一遍：</p><ol><li><code>pwd</code> → <code>ls -la /</code> → 熟悉根目录结构</li><li><code>mkdir -p /opt/apps/test-api/logs</code> → 创建应用目录</li><li><code>echo &quot;hello&quot; &gt; /opt/apps/test-api/logs/app.log</code> → 写个测试日志</li><li><code>tail -f /opt/apps/test-api/logs/app.log</code> → 另开终端追踪（Ctrl+C 退出）</li><li><code>df -h</code> → 看磁盘使用情况</li><li><code>du -sh /var/*</code> → 看 /var 下谁最占空间</li><li><code>find / -name &quot;*.conf&quot; -path &quot;*/nginx/*&quot;</code> → 找 Nginx 配置文件</li><li><code>grep -rn &quot;listen&quot; /etc/nginx/</code> → 在 Nginx 配置里搜端口</li><li>配置一个日志轮转：创建 <code>/etc/logrotate.d/test-api</code></li><li><code>tar -czf test-backup.tar.gz /opt/apps/test-api/</code> → 打个备份包</li></ol><p>全部跑通了，说明文件系统这块你够用了。</p>`,65)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};